#!/usr/bin/env python3
"""Cat diagnosis_ja enrichment — batch 13 (60 entries)."""
import json
import os
import time

JSON_PATH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "diseases_all_species.json")

ENRICHMENTS: dict[str, dict[str, str]] = {}

ENRICHMENTS["cat_feline_chronic_hepatopathy"] = {"diagnosis_ja": "慢性的な食欲不振・体重減少・嘔吐・黄疸を呈する。血液化学でALT/AST持続上昇、ALP/GGT上昇、低Alb血症を認める。総胆汁酸上昇で肝機能低下を確認。腹部超音波で肝臓のサイズ・エコー輝度変化を評価。凝固系検査でPT/APTT延長を確認。確定診断は超音波ガイド下肝生検（線維化・炎症・銅蓄積の評価）。肝リピドーシス、胆管炎、肝腫瘍との鑑別が必要。三臓器炎の併発を膵特異的リパーゼで評価。"}
ENRICHMENTS["cat_feline_splenic_torsion"] = {"diagnosis_ja": "急性腹痛・嘔吐・虚脱・蒼白粘膜を呈する。腹部触診で腫大した脾臓を触知。腹部超音波で脾臓の腫大、脾門部血管の異常、脾実質のエコー輝度不均一を確認。カラードプラで脾臓血流の途絶を評価。PCV低下（脾臓内出血）。CBC/血液化学で脱水・代謝異常を評価。腹部X線で軟部組織腫瘤と腹水を確認。脾臓腫瘍、脾臓血腫、GDV（犬で多い）との鑑別が必要。緊急脾臓摘出術が適応。"}
ENRICHMENTS["cat_feline_mesenteric_volvulus"] = {"diagnosis_ja": "急性の激しい腹痛・嘔吐・ショック・急速な全身状態悪化を呈する。腹部X線で腸管の著明なガス拡張を確認。腹部超音波で腸管壁の浮腫・腸間膜血管の絞扼・腹水を評価。CBC/血液化学で乳酸アシドーシス（乳酸値>4mmol/L）、BUN/Cre上昇を認める。凝固系検査でDIC合併を評価。腹腔穿刺で血性腹水を認める場合は腸管壊死を示唆。猫では極めて稀。腸閉塞、膵炎、腸重積との鑑別が必要。緊急開腹術が必要。"}
ENRICHMENTS["cat_feline_focal_seizure_disorder"] = {"diagnosis_ja": "顔面攣縮・片側性痙攣・流涎・異常行動（フライバイティング、旋回）を認める。全般発作への二次性般化を伴うことがある。発作の動画記録が診断に有用。神経学的検査で発作間欠期の局在性異常を評価。MRIで構造的病変（腫瘍、炎症、血管障害）を検索。脳波検査（EEG）で焦点性てんかん波を確認。CBC/血液化学/T4で代謝性原因を除外。CSF分析で炎症性疾患を評価。特発性てんかん、脳腫瘍、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_feline_status_epilepticus"] = {"diagnosis_ja": "5分以上持続する痙攣発作、または意識回復なく連続する発作を認める。救急対応：気道確保・SpO2モニタリング・体温管理。血糖値即座測定（低血糖を除外）。CBC/血液化学で代謝性原因を検索。血液ガスで代謝性アシドーシスを評価。乳酸値上昇、CK上昇は持続的な筋活動を反映。血中抗てんかん薬濃度測定（既治療例）。MRIで構造的病変を評価。中毒（有機リン、鉛、メタアルデヒド）、FIP、脳腫瘍との鑑別。重積持続時は脳浮腫リスク。"}
ENRICHMENTS["cat_feline_brachial_plexus_avulsion"] = {"diagnosis_ja": "前肢の弛緩性麻痺・感覚喪失を認める。外傷（交通事故・高所落下）歴を確認。神経学的検査で罹患前肢の橈骨神経・正中神経・尺骨神経の機能を個別評価。パニキュラス反射消失レベルで損傷範囲を推定。筋電図で脱神経電位を確認（受傷後5-7日以降）。頸椎MRIで神経根離断と脊髄への影響を評価。ホルネル症候群の併発は下位節前損傷を示唆。深部痛覚の有無が予後指標。末梢神経腫瘍、脊髄疾患との鑑別が必要。"}
ENRICHMENTS["cat_feline_horner_syndrome"] = {"diagnosis_ja": "縮瞳・瞬膜突出・眼瞼下垂・眼球陥凹の4徴候を認める。薬理学的瞳孔試験で障害部位を同定（1%フェニレフリン：節後障害は20分以内に散瞳、節前は45分以上）。耳鏡検査で中耳疾患を評価。頸部〜胸部X線で縦隔腫瘤・肺尖部腫瘤を検索。CT/MRIで交感神経経路の病変を検索（中耳、頸部、前縦隔、脳幹）。中耳炎が猫の最も多い原因。特発性は排除診断。中耳腫瘍、リンパ腫、外傷との鑑別が必要。"}
ENRICHMENTS["cat_feline_spinal_cord_trauma"] = {"diagnosis_ja": "外傷後の急性不全麻痺〜完全麻痺を呈する。交通事故・高所落下の既往を確認。ABCDE法でトリアージ後、神経学的検査で麻痺のレベル（頸髄・胸腰髄・腰仙髄）を同定。脊椎X線で骨折・脱臼を確認。MRIで脊髄実質の浮腫・出血・圧迫の程度を評価（T2高信号の範囲が予後に相関）。深部痛覚の有無が予後指標（消失は重度）。PCV/TP連続測定で出血を監視。膀胱機能の評価が重要。椎間板ヘルニア、脊髄腫瘍との鑑別が必要。"}
ENRICHMENTS["cat_feline_degenerative_myelopathy"] = {"diagnosis_ja": "進行性の後肢不全麻痺・運動失調を認める中高齢猫。神経学的検査で上位運動ニューロン徴候（後肢反射亢進、ナックリング）を確認。脊椎X線/MRIで圧迫性脊髄疾患を除外（本疾患ではMRIは通常正常）。CSF分析で炎症性疾患を除外。確定診断は剖検（脊髄白質の変性・脱髄）。SOD1遺伝子変異検査（猫では犬ほど確立されていない）。排除診断が中心。椎間板ヘルニア、脊髄腫瘍、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_feline_syringomyelia"] = {"diagnosis_ja": "頸部痛・搔痒様動作（ファントムスクラッチング）・四肢不全麻痺を認める。MRIで脊髄中心管の拡大（空洞形成）を確認（T2高信号の液体信号）。キアリ様奇形の合併を評価（後頭骨低形成・小脳ヘルニア）。CSF分析で炎症性疾患を除外。神経学的検査で罹患レベルに応じた感覚・運動障害を評価。脊髄の二次性変化（脱髄・グリオーシス）の程度が予後に相関。脊髄腫瘍、椎間板ヘルニア、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_feline_chronic_pain_syndrome"] = {"diagnosis_ja": "慢性的な行動変化（活動性低下、ジャンプ回避、攻撃性増加、グルーミング低下/過剰）を呈する。疼痛スケール（Glasgow Feline Composite Pain Scale等）による客観的評価。身体検査で関節可動域・筋肉触診・脊椎触診を実施。X線で変形性関節症・椎間板疾患を評価。CBC/血液化学/T4で基礎疾患を検索。疼痛部位の特定が困難な場合、画像診断（超音波、CT、MRI）を段階的に実施。NSAIDs試験的投与への反応で診断的治療。"}
ENRICHMENTS["cat_feline_night_vocalization_syndrome"] = {"diagnosis_ja": "夜間の過度な発声（鳴き声）を認める。高齢猫に多い。甲状腺機能亢進症（T4上昇）を最優先で除外。血圧測定で全身性高血圧を確認（高血圧性脳症）。CBC/血液化学/尿検査で代謝性疾患（CKD、糖尿病）を評価。聴力検査で難聴を評価。眼底検査で高血圧性網膜症（視力喪失）を確認。認知機能障害（CDS）は行動問診票で評価。疼痛（関節炎等）の検索。脳腫瘍、FIPによる神経症状との鑑別が必要。"}
ENRICHMENTS["cat_feline_litter_box_aversion"] = {"diagnosis_ja": "トイレ以外の場所での排泄を認める。詳細な行動歴聴取（発症時期、トリガー、排泄場所の嗜好）が不可欠。身体検査と尿検査で泌尿器疾患（FIC、尿路結石、UTI）を除外。血液化学/T4で代謝性原因を検索。腹部超音波で膀胱・腎臓の異常を評価。便検査で消化器疾患を除外。トイレ環境の評価（サイズ、砂の種類、清掃頻度、設置場所、猫数）。マーキング行動、分離不安、多頭飼育ストレスとの鑑別が重要。"}
ENRICHMENTS["cat_feline_noise_phobia"] = {"diagnosis_ja": "特定の音刺激（雷、花火、工事音）に対する過度の恐怖反応（逃避、隠れる、振戦、排泄）を認める。行動歴の詳細聴取でトリガーと反応パターンを記録。身体検査でT4測定（甲状腺機能亢進症）、CBC/血液化学で代謝性原因を除外。聴力検査で聴覚過敏を評価。同居環境のストレス要因を評価。留守番カメラで客観的な行動評価。全般性不安障害、分離不安、痛みに関連した行動変化との鑑別が必要。環境改善と脱感作プログラムの計画。"}
ENRICHMENTS["cat_feline_psychogenic_polydipsia"] = {"diagnosis_ja": "著明な多飲多尿を呈するが器質的疾患が除外される。血液化学でBUN/Cre正常、血糖正常、電解質正常を確認。T4測定で甲状腺機能亢進症を除外。尿検査で低比重尿（<1.030）を確認。水制限試験で尿濃縮能は正常（比重>1.045に上昇）。血清浸透圧低値〜正常。腎臓超音波で構造的異常を除外。飼育環境・ストレス要因の評価。CKD、糖尿病、甲状腺機能亢進症、尿崩症（中枢性・腎性）との鑑別が必要。排除診断。"}
ENRICHMENTS["cat_feline_feline_infectious_anemia_candidatus_m._haemominutum"] = {"diagnosis_ja": "Ca. M. haemominutumは猫ヘモプラズマの中で最も低病原性。健常猫では不顕性感染が多い。免疫抑制猫（FIV/FeLV、ステロイド投与）で軽度〜中等度の貧血を引き起こす。CBC軽度貧血（PCV 25-30%）。血液塗抹での菌体検出は困難。リアルタイムPCR検査（種特異的プライマー）で確定。M. haemofelisとの混合感染を評価。FIV/FeLV検査は必須。IMHA、FeLV関連貧血、鉄欠乏性貧血との鑑別が必要。"}
ENRICHMENTS["cat_feline_listeriosis"] = {"diagnosis_ja": "発熱・旋回運動・頭部傾斜・顔面神経麻痺など脳幹徴候を呈する。汚染された生肉・乳製品の摂取歴を確認。CBC単球増多を認めることがある。CSF分析で好中球優位の細胞数増加・蛋白上昇を確認。CSF/血液からのListeria monocytogenes培養で確定。MRIで脳幹のT2高信号病変を確認。PCR検査の感度が高い。FIP、トキソプラズマ症、クリプトコッカス症、脳幹腫瘍との鑑別が必要。人畜共通感染症として公衆衛生上の注意が必要。"}
ENRICHMENTS["cat_feline_leptospirosis"] = {"diagnosis_ja": "急性腎不全（嘔吐、多飲多尿、BUN/Cre上昇）・発熱・黄疸を呈する。猫では犬より発症率は低いが感染は報告されている。CBC白血球増多、血小板減少。血液化学で肝酵素上昇、T-Bil上昇、BUN/Cre上昇を認める。尿検査で円柱・蛋白尿。PCR検査（血液・尿）で確定。MAT（顕微鏡的凝集試験）でペア血清4倍以上の上昇。暗視野顕微鏡で尿中のスピロヘータを検索。急性腎障害、肝リピドーシスとの鑑別が必要。人畜共通感染症。"}
ENRICHMENTS["cat_feline_feline_papillomatosis"] = {"diagnosis_ja": "口腔内〜皮膚の有茎性乳頭状腫瘤を認める。FeLV/FIV陽性猫や免疫抑制猫に好発。口腔内検査で疣贅様病変を確認。FNA/生検で角化過多を伴う乳頭状上皮増殖を確認。免疫組織化学でパピローマウイルス抗原を検出。PCR検査でウイルスDNAを同定（FcaPV-1/2等）。悪性転化（SCC）のリスクがあるためモニタリングが必要。扁平上皮癌、線維乳頭腫、好酸球性肉芽腫との鑑別が必要。免疫状態の評価が重要。"}
ENRICHMENTS["cat_feline_subcutaneous_abscess_non-bite"] = {"diagnosis_ja": "皮下の波動性腫脹・疼痛・発熱を認める（咬傷以外の原因）。注射後反応、異物反応、手術部位感染を鑑別。波動性腫瘤の穿刺で膿汁を採取し細菌培養・感受性試験を実施。嫌気性菌を含む培養が重要。CBC白血球増多（好中球左方移動）。発熱時のFIV/FeLV検査。超音波で膿瘍腔のサイズ・隔壁を評価。注射部位肉腫（FISS）との鑑別が猫では特に重要（注射部位の腫瘤は生検を検討）。腫瘍、嚢胞、血腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_necrotizing_fasciitis"] = {"diagnosis_ja": "急速に進行する皮膚・皮下組織の壊死、激しい疼痛（病変の範囲に不釣り合いな疼痛）、発熱・ショック徴候を呈する。CBC白血球増多（左方移動）または白血球減少（予後不良）、CRP著明上昇。血液培養で菌血症を評価。皮膚病変部のグラム染色・培養で起因菌を同定。CT/MRIで筋膜面に沿った炎症進展を評価。外科的デブリードマン時の肉眼所見で筋膜壊死を確認。蜂窩織炎、単純膿瘍、ガス壊疽との鑑別が必要。"}
ENRICHMENTS["cat_feline_dental_malocclusion"] = {"diagnosis_ja": "不正咬合による採食困難・流涎・口腔損傷を認める。口腔内検査で上下顎の関係（アンダーショット/オーバーショット）、歯列の異常を評価。歯科X線で歯根の位置関係・歯根吸収を確認。短頭種（ペルシャ）は下顎前突（アンダーバイト）が好発。乳歯遺残の確認。軟部組織損傷（口蓋穿孔、歯肉外傷）の評価。頭部X線/CTで顎骨の対称性・TMJ構造を評価。歯周病、FORL、口腔腫瘍との鑑別が必要。"}
ENRICHMENTS["cat_feline_oral_squamous_cell_carcinoma_sublingual"] = {"diagnosis_ja": "舌下〜口腔底の潰瘍性腫瘤として発見。流涎・採食困難・口臭・血性分泌物を認める。口腔内検査で腫瘤の位置・サイズ・浸潤範囲を確認。生検による組織病理で確定（分化度と浸潤パターンを評価）。CT検査で下顎骨・舌骨への浸潤を詳細に評価。所属リンパ節のFNA検査。胸部X線で肺転移を検索。CBC/血液化学は通常正常だが、高Ca血症を伴うことがある。好酸球性肉芽腫、口腔メラノーマ、リンパ腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_enamel_hypoplasia"] = {"diagnosis_ja": "歯表面の凹凸・変色（黄褐色）・エナメル質の部分的欠損を認める。乳歯期のパルボウイルス感染、高熱、栄養障害、フッ素過剰が原因。歯科X線でエナメル質の菲薄化を確認。プローブ検査でエナメル質の脆弱性を評価。罹患歯は齲蝕・歯周病のリスクが高い。全歯評価で罹患範囲を記録。FORL（猫の歯の吸収性病変）との鑑別が重要。歯髄露出時は歯内療法の適応を検討。齲歯、外傷性歯冠破折との鑑別が必要。"}
ENRICHMENTS["cat_feline_oronasal_fistula"] = {"diagnosis_ja": "くしゃみ・片側性鼻汁・採食時の鼻腔への食物漏出を認める。口腔内検査で口蓋の穿孔部位を確認（上顎犬歯抜歯後が最多）。歯科プローブで瘻孔の大きさを評価。歯科X線で隣接歯の歯根病変を検索。鼻汁の細菌培養は二次感染評価。CT検査で鼻腔の二次的変化を評価。硬口蓋腫瘍による穿孔、外傷性穿孔、先天性口蓋裂との鑑別が必要。手術的フラップ閉鎖が標準治療。"}
ENRICHMENTS["cat_feline_chronic_rhinitis_non-infectious"] = {"diagnosis_ja": "3週間以上持続する鼻汁・くしゃみ・いびき様呼吸を認める。感染性原因が除外された慢性鼻炎。CT検査で鼻甲介の破壊・リモデリング・粘膜肥厚を評価。鼻腔鏡検査で粘膜の炎症・ポリープ・腫瘤の有無を確認。鼻腔生検で組織病理学的評価（リンパ形質細胞性、好酸球性）。鼻汁の細菌・真菌培養。クリプトコッカス抗原検査。アレルギー検査。鼻腔腫瘍（リンパ腫、SCC）、鼻腔真菌症、異物との鑑別が必要。"}
ENRICHMENTS["cat_feline_aural_hematoma"] = {"diagnosis_ja": "耳介の波動性腫脹（耳介軟骨と皮膚の間の血液貯留）を認める。外耳炎に伴う頭振り・耳掻きが誘因。耳鏡検査で外耳炎の基礎疾患を評価。穿刺吸引で血液〜血性漿液を確認。CBC凝固系検査で出血傾向を除外（稀だが評価は重要）。血腫の再発予防には基礎疾患（外耳炎、アレルギー）の治療が不可欠。穿刺のみでは再発率高い。耳介腫瘍、耳介膿瘍との鑑別が必要。慢性化すると耳介変形（カリフラワー耳）を生じる。"}
ENRICHMENTS["cat_feline_nasopharyngeal_stenosis"] = {"diagnosis_ja": "吸気性ストライダー・いびき・鼻汁・開口呼吸を呈する。上気道感染後の瘢痕形成が最多の原因。口腔検査で軟口蓋背側に狭窄が見えることがある。CT検査で鼻咽頭腔の狭窄の範囲と程度を評価。鼻咽頭内視鏡で膜状〜管状の狭窄を直接確認。透視検査で呼吸相の変化を評価。全身麻酔下での評価が必要。鼻咽頭ポリープ、鼻腔腫瘍、鼻腔異物、先天性鼻咽頭狭窄との鑑別が必要。バルーン拡張術が治療の第一選択。"}
ENRICHMENTS["cat_feline_idiopathic_chylothorax"] = {"diagnosis_ja": "呼吸困難・浅速呼吸・運動不耐性を呈する。胸部X線で胸水貯留を確認。胸水穿刺で乳白色の液体を採取。胸水分析でTG>100mg/dL、コレステロール<TG、乳び試験陽性を確認。胸水細胞診で成熟リンパ球優位。既知の原因（心不全、前縦隔腫瘤、外傷、フィラリア）を除外してidiopathicと診断。心エコーで心疾患を検索。胸部CT/リンパ管造影で胸管の形態を評価。リンパ腫、心不全、膿胸との鑑別が必要。"}
ENRICHMENTS["cat_feline_fungal_rhinitis"] = {"diagnosis_ja": "慢性鼻汁（膿性〜出血性）・くしゃみ・顔面変形を呈する。CT検査で鼻腔内の軟部組織陰影と骨溶解を確認。鼻腔鏡検査で真菌プラークを直接観察。鼻汁/組織の真菌培養でCryptococcus、Aspergillus、Penicillium等を同定。クリプトコッカス抗原検査（LCAT）が高感度。組織生検でGMS/PAS染色陽性の菌体を確認。免疫状態の評価（FIV/FeLV）。鼻腔腫瘍、慢性鼻炎、鼻腔異物との鑑別が必要。"}
ENRICHMENTS["cat_feline_idiopathic_vestibular_disease"] = {"diagnosis_ja": "急性発症の頭部傾斜・眼振（水平〜回旋性）・運動失調・嘔吐を呈する。末梢性前庭障害を示唆する所見（水平眼振は頭位で方向変化なし、ホルネル症候群合併なら中耳病変）。耳鏡検査で外耳・鼓膜を確認。CT/MRIで中耳/内耳病変・脳幹病変を除外。CBC/血液化学/T4で代謝性原因を除外。特発性は排除診断で、2-3週で自然改善する。中耳炎、内耳腫瘍、脳幹腫瘍、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_feline_nasal_foreign_body"] = {"diagnosis_ja": "急性発症の片側性くしゃみ・鼻汁・前足で鼻をこする動作を認める。草の葉・種子が多い。経過が長いと膿性鼻汁に変化。CT検査で鼻腔内の異物と二次的な粘膜腫脹を確認。鼻腔鏡検査で異物を直接確認し除去（診断と治療を兼ねる）。X線は放射線不透過性異物のみ検出可能。CBC/CRP上昇は二次感染を示唆。鼻腔腫瘍、鼻腔真菌症、慢性鼻炎との鑑別が必要。後方鼻腔鏡と前方鼻腔鏡の両方を実施。"}
ENRICHMENTS["cat_feline_esophageal_stricture"] = {"diagnosis_ja": "固形物の嘔吐（逆流）・食後の吐出・体重減少を呈する。液体は通過可能。麻酔関連逆流・食道異物・腐食性物質摂取の既往を確認。バリウム造影で食道の限局性狭窄を確認。透視検査で食道通過障害を動的に評価。内視鏡検査で狭窄部位を直接観察し、程度を評価。食道腫瘍、食道外圧迫（縦隔腫瘤）、食道運動障害との鑑別が必要。吸引性肺炎の合併を胸部X線で評価。バルーン拡張術が第一選択治療。"}
ENRICHMENTS["cat_feline_gastric_motility_disorder"] = {"diagnosis_ja": "食後の嘔吐（消化途中の食物を含む）・早期満腹感・腹部膨満を呈する。腹部X線で胃内のガス/食物貯留を確認。バリウム造影透視で胃排出遅延を評価（正常の猫は投与後4-6時間で排出）。腹部超音波で胃壁の異常・幽門部肥厚を検索。血液化学で電解質異常（低K）・代謝性原因を除外。内視鏡検査で胃粘膜病変・幽門狭窄を評価。甲状腺機能検査。自律神経障害の評価。幽門狭窄、胃腫瘍、巨大食道症との鑑別が必要。"}
ENRICHMENTS["cat_nasal_lymphoma"] = {"diagnosis_ja": "慢性鼻汁（片側性→両側性）・くしゃみ・鼻出血・顔面変形を呈する。CT/MRIで鼻腔内の軟部組織腫瘤と骨溶解を確認。鼻腔鏡検査で腫瘤を直接観察し生検を実施。組織病理で悪性リンパ球の浸潤を確認。免疫組織化学（CD3/CD20/CD79a）でB細胞性vsT細胞性を判定。CBC/血液化学で全身性の異常を評価。FeLV/FIV検査。胸腹部CTで全身ステージングを実施。鼻腔SCC、クリプトコッカス症、慢性鼻炎との鑑別が必要。"}
ENRICHMENTS["cat_large_granular_lymphocyte_lymphoma"] = {"diagnosis_ja": "消化器症状（嘔吐、下痢、体重減少）を主徴とする高悪性度リンパ腫。腹部超音波で腸管壁肥厚・腸間膜リンパ節腫大を確認。FNA/生検で大型顆粒リンパ球（NK/T細胞マーカー陽性、細胞質内アズール顆粒）を確認。免疫組織化学でCD3+、Granzyme B+。CBC/血液化学で貧血・低蛋白を評価。FeLV検査。骨髄検査で浸潤を評価。末梢血塗抹で白血病化を確認。IBD、小細胞型リンパ腫、肥満細胞腫との鑑別が必要。予後不良。"}
ENRICHMENTS["cat_oral_melanoma"] = {"diagnosis_ja": "口腔内（歯肉・口蓋・頬粘膜）の色素沈着〜無色素性腫瘤を認める。流涎・口臭・採食困難・血性分泌物を伴う。生検による組織病理で確定。免疫組織化学（Melan-A、S100、PNL-2）で特に無色素性の場合に重要。歯科X線/CTで骨浸潤を評価。所属リンパ節のFNA検査。胸部X線で肺転移を検索。猫の口腔メラノーマは犬ほど一般的ではないが高悪性度。SCC、好酸球性肉芽腫、エプリスとの鑑別が必要。"}
ENRICHMENTS["cat_apocrine_gland_adenocarcinoma"] = {"diagnosis_ja": "皮膚・皮下の結節性腫瘤として発見。好発部位は腋窩・鼠径部・頭頸部。FNA細胞診で腺上皮様の異型細胞を認める。切除生検による組織病理で確定（管腔形成を伴う異型腺上皮の浸潤性増殖）。CT/MRIで腫瘤の浸潤範囲を術前評価。所属リンパ節のFNA検査でステージング。胸部X線で肺転移を検索。CBC/血液化学は通常正常。アポクリン腺腫（良性）、注射部位肉腫、肥満細胞腫との鑑別が必要。"}
ENRICHMENTS["cat_bronchogenic_carcinoma"] = {"diagnosis_ja": "慢性咳嗽・呼吸困難・体重減少を呈する。胸部X線で肺野の孤立性〜多発性結節影を確認。CT検査で腫瘤の範囲・縦隔リンパ節腫大・胸壁浸潤を評価。CTガイド下FNA/経気管支生検で細胞診を実施。気管支鏡検査で気管支内腫瘤を観察。BAL液細胞診で悪性細胞を検索。胸水がある場合は細胞診を実施。CBC/血液化学は通常正常だが、傍腫瘍性高Ca血症を呈することがある。肺転移（他部位原発）、リンパ腫、肉芽腫性疾患との鑑別が必要。"}
ENRICHMENTS["cat_thymic_lymphoma"] = {"diagnosis_ja": "若齢〜中齢猫の呼吸困難・前肢浮腫・嚥下困難を呈する。胸部X線で前縦隔の巨大腫瘤を確認。胸水細胞診でリンパ芽球を検出。FNA細胞診で大型均一なリンパ芽球を確認。免疫組織化学でT細胞マーカー（CD3）陽性が多い。FeLV検査（若齢猫の胸腺リンパ腫はFeLV関連が多い）。CBC/血液化学で高Ca血症を評価。胸腹部CT/超音波でステージング。胸腺腫、心基底部腫瘍、胸腺癌との鑑別が必要。"}
ENRICHMENTS["cat_thymic_carcinoma"] = {"diagnosis_ja": "前縦隔腫瘤による呼吸困難・胸水貯留を呈する。高齢猫に好発。胸部X線/CTで前縦隔の不均一な腫瘤を確認。FNA細胞診で上皮性の異型細胞を認める。確定は切除/生検による組織病理（胸腺上皮由来の悪性腫瘍、リンパ球浸潤は少ない）。免疫組織化学でサイトケラチン陽性、CD3陰性。FeLV/FIV検査。CBC/血液化学で傍腫瘍症候群を評価。胸腺リンパ腫、胸腺腫、心基底部腫瘍との鑑別が必要。"}
ENRICHMENTS["cat_hepatic_lymphoma"] = {"diagnosis_ja": "食欲不振・体重減少・嘔吐・黄疸を呈する。血液化学でALT/AST上昇、ALP/GGT上昇、T-Bil上昇を認める。腹部超音波で肝臓のエコー輝度変化（低エコー結節、不均一パターン）を確認。超音波ガイド下FNA細胞診で均一な異型リンパ球を検出。確定は組織生検。免疫組織化学でT/B細胞分類。FeLV/FIV検査。骨髄検査と全身CTでステージング。肝リピドーシス、胆管炎、肝細胞癌、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_splenic_mast_cell_tumor"] = {"diagnosis_ja": "脾腫が主な所見（無症状〜腹部膨満・食欲不振・嘔吐）。腹部超音波で脾臓の腫大・多発性低エコー結節を確認。脾臓FNA細胞診で顆粒を含む肥満細胞を検出（トルイジンブルー染色で確認）。CBC好塩基球増多・肥満細胞血症を認めることがある。内臓型MCTはc-KIT変異の評価が治療方針に影響。胸腹部CTでステージング。骨髄検査で浸潤を評価。脾臓リンパ腫、脾臓血管肉腫、脾臓過形成との鑑別が必要。"}
ENRICHMENTS["cat_intestinal_mast_cell_tumor"] = {"diagnosis_ja": "慢性嘔吐・下痢・体重減少を呈する。腹部超音波で腸管壁の限局性〜瀰漫性肥厚を確認。腸間膜リンパ節腫大を伴う。腹部FNA/内視鏡生検で肥満細胞を検出。脾臓・肝臓の併発を腹部超音波で評価（内臓型MCT三臓器浸潤）。CBC末梢血塗抹で循環肥満細胞を検索。c-KIT免疫組織化学とKIT変異検査。骨髄穿刺でステージング。腸管リンパ腫、GIST、腺癌との鑑別が必要。組織学的グレーディングが予後に相関。"}
ENRICHMENTS["cat_feline_enteric_coronavirus_non-fip"] = {"diagnosis_ja": "軽度の消化器症状（軟便・一過性の下痢）を呈する若齢猫。多頭飼育環境に好発。多くは無症候性。糞便中コロナウイルスRT-PCR陽性で感染を確認（ただしFIP株との区別は困難）。血清抗コロナウイルス抗体価上昇は感染歴を示す（FIP診断には不十分）。CBC/血液化学は通常正常。A/G比正常（FIPでは低下）。FIPとの鑑別が最重要課題（FIPでは持続的な発熱、腹水/胸水、高γグロブリン血症）。パルボウイルス、トリトリコモナスとの鑑別も必要。"}
ENRICHMENTS["cat_mycobacterium_bovis_infection"] = {"diagnosis_ja": "慢性の排膿性皮膚結節・リンパ節腫大・消化器症状・呼吸器症状を呈する。ツベルクリン反応は猫では信頼性が低い。FNA/組織生検で肉芽腫性炎症と抗酸菌を確認（チール・ネールゼン染色陽性桿菌）。培養は確定的だが4-8週を要する。PCR検査で種同定と迅速診断。胸部X線で肺結節を検索。CBC/血液化学で炎症マーカーを評価。人畜共通感染症として公衆衛生上の報告義務あり。非結核性抗酸菌症、リンパ腫、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_mycobacterium_avium_complex_infection"] = {"diagnosis_ja": "免疫抑制猫での消化器症状（慢性下痢、体重減少）、リンパ節腫大、肝脾腫を呈する。アビシニアン・ソマリに品種素因。FNA/組織生検で多数の抗酸菌を含むマクロファージ（肉芽腫性炎症）を確認。チール・ネールゼン染色陽性。培養・PCRで種同定。血液化学で肝酵素上昇・低Alb血症。CBC汎血球減少を認めることがある。FIV/FeLV検査で免疫状態を評価。リンパ腫、FIP、ヒストプラズマ症との鑑別が必要。"}
ENRICHMENTS["cat_cryptococcus_neoformans_meningitis"] = {"diagnosis_ja": "神経症状（発作、旋回、意識障害）・発熱・頸部硬直を呈する。鼻腔病変からの播種が多い。CSF分析で蛋白上昇・単核球優位の細胞数増加。CSF墨汁染色で莢膜を有する酵母菌体を確認。血清/CSFクリプトコッカス抗原（LCAT）陽性で確定（高感度・高特異度）。MRIで脳実質の肉芽腫性病変と髄膜造影増強を評価。真菌培養で種同定。FIV/FeLV検査。FIP、トキソプラズマ症、リンパ腫による髄膜浸潤との鑑別が必要。"}
ENRICHMENTS["cat_sporothrix_schenckii_infection"] = {"diagnosis_ja": "皮膚の結節性潰瘍（排膿性）がリンパ管に沿って連珠状に進展する。外傷・刺創歴を確認。FNA/排膿液のPAS/GMS染色で葉巻型の酵母菌体を確認（猫では菌量が多く検出しやすい）。真菌培養で確定（25°Cで菌糸型、37°Cで酵母型の二形性）。組織生検で肉芽腫性〜化膿性炎症と菌体を確認。FIV/FeLV検査で免疫状態を評価。人畜共通感染症（猫からヒトへの感染が多い）として取扱いに注意。非結核性抗酸菌症、ノカルジア症との鑑別が必要。"}

def apply_enrichments() -> None:
    for attempt in range(3):
        try:
            with open(JSON_PATH, encoding="utf-8") as f:
                content = f.read()
            decoder = json.JSONDecoder()
            data, _ = decoder.raw_decode(content)
            break
        except (json.JSONDecodeError, ValueError):
            if attempt < 2:
                time.sleep(5)
            else:
                raise
    updated = 0
    for entry in data:
        eid = entry.get("id")
        if eid in ENRICHMENTS:
            for k, v in ENRICHMENTS[eid].items():
                entry[k] = v
            updated += 1
    with open(JSON_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Updated {updated}/{len(ENRICHMENTS)} entries")

if __name__ == "__main__":
    apply_enrichments()
